package com.stark.automation.api.clients;
import com.stark.automation.api.endpoints.ApiEndpoints; import com.stark.automation.api.models.request.PostRequest; import com.stark.automation.api.models.response.PostResponse; import com.stark.automation.api.specifications.RequestSpecifications; import io.restassured.response.Response; import static io.restassured.RestAssured.given;
public class PostClient { public Response get(int id) { return given().spec(RequestSpecifications.json()).when().get(ApiEndpoints.POSTS + "/" + id); } public Response create(PostRequest request) { return given().spec(RequestSpecifications.json()).body(request).when().post(ApiEndpoints.POSTS + "/add"); } public Response updateTitle(int id, String title) { return given().spec(RequestSpecifications.json()).body(java.util.Map.of("title", title)).when().put(ApiEndpoints.POSTS + "/" + id); } public Response delete(int id) { return given().spec(RequestSpecifications.json()).when().delete(ApiEndpoints.POSTS + "/" + id); } public PostResponse getAsModel(int id) { return get(id).as(PostResponse.class); } }
